package com.bank.bridge;

import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// Simulates the Python <-> JVM boundary. Every crossing serializes bytes and costs latency.
class Py4JBridge {
    private static final Logger log = Logger.getLogger(Py4JBridge.class.getName());

    private final long bytesPerValue;
    private final long perCrossingPenaltyNs;

    private final AtomicLong crossings = new AtomicLong();
    private final AtomicLong bytesMoved = new AtomicLong();
    private final AtomicLong simulatedNanos = new AtomicLong();

    Py4JBridge(long bytesPerValue, long perCrossingPenaltyNs) {
        this.bytesPerValue = bytesPerValue;
        this.perCrossingPenaltyNs = perCrossingPenaltyNs;
    }

    // Records one crossing carrying `valueCount` values in each direction (out and back).
    void cross(long valueCount) {
        crossings.incrementAndGet();
        bytesMoved.addAndGet(valueCount * bytesPerValue * 2); // round trip
        simulatedNanos.addAndGet(perCrossingPenaltyNs);       // fixed per-crossing cost
    }

    void report(String label) {
        log.info(() -> String.format(
            "%-18s crossings=%,d  bytesMoved=%,d  simulatedCostMs=%.2f",
            label, crossings.get(), bytesMoved.get(), simulatedNanos.get() / 1_000_000.0));
    }
}
