package com.bank.bridge;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.logging.Logger;

// Plain Python UDF: crosses the bridge ONCE PER ROW. Worst case.
class PythonUdfProcessor {
    private static final Logger log = Logger.getLogger(PythonUdfProcessor.class.getName());
    private static final BigDecimal RATE = new BigDecimal("0.0005");

    private final Py4JBridge bridge;

    PythonUdfProcessor(Py4JBridge bridge) { this.bridge = bridge; }

    void computeFees(List<Trade> trades) {
        log.warning(() -> "Plain Python UDF: one boundary crossing PER ROW for " + trades.size() + " rows");
        for (Trade t : trades) {
            bridge.cross(1);                       // serialize this one amount out and back
            t.fee = t.amount.multiply(RATE).setScale(2, RoundingMode.HALF_UP);
        }
    }
}
