package com.bank.bridge;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.logging.Logger;

// Pandas (vectorized) UDF: crosses the bridge ONCE PER BATCH via Arrow columnar transfer.
class PandasUdfProcessor {
    private static final Logger log = Logger.getLogger(PandasUdfProcessor.class.getName());
    private static final BigDecimal RATE = new BigDecimal("0.0005");

    private final Py4JBridge bridge;
    private final int batchSize;

    PandasUdfProcessor(Py4JBridge bridge, int batchSize) {
        this.bridge = bridge;
        this.batchSize = batchSize;
    }

    void computeFees(List<Trade> trades) {
        log.info(() -> "Pandas UDF: one crossing PER BATCH of " + batchSize + " via Arrow");
        for (int start = 0; start < trades.size(); start += batchSize) {
            int end = Math.min(start + batchSize, trades.size());
            List<Trade> batch = trades.subList(start, end);
            bridge.cross(batch.size());            // whole batch crosses together
            for (Trade t : batch) {
                t.fee = t.amount.multiply(RATE).setScale(2, RoundingMode.HALF_UP);
            }
        }
    }
}
