package com.bank.bridge;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

// Holds trade rows as native JVM objects, like Spark's executors.
class JvmEngine {
    private final List<Trade> trades = new ArrayList<>();

    void loadTrades(int count) {
        for (int i = 1; i <= count; i++) {
            String acct = (i % 2 == 0) ? "CUR3001" : "SAV2001";
            trades.add(new Trade("TRD-" + i, acct, new BigDecimal(1000 + i)));
        }
    }

    List<Trade> rows() { return trades; }

    // Returns a fresh copy so each processor starts clean.
    List<Trade> freshCopy() {
        List<Trade> copy = new ArrayList<>(trades.size());
        for (Trade t : trades) copy.add(new Trade(t.tradeId, t.accountId, t.amount));
        return copy;
    }
}
