package com.bank.bridge;

import java.util.List;
import java.util.logging.Logger;

public class BridgeDemo {
    private static final Logger log = Logger.getLogger(BridgeDemo.class.getName());

    public static void main(String[] args) {
        int rowCount = 100_000;
        long bytesPerValue = 8;
        long penaltyNs = 50_000;
        int batchSize = 10_000;

        JvmEngine engine = new JvmEngine();
        engine.loadTrades(rowCount);
        log.info(() -> "Loaded " + rowCount + " trades into the JVM engine");

        // 1) Plain Python UDF — crossing per row.
        Py4JBridge b1 = new Py4JBridge(bytesPerValue, penaltyNs);
        new PythonUdfProcessor(b1).computeFees(engine.freshCopy());
        b1.report("PythonUDF");

        // 2) Pandas UDF — crossing per batch.
        Py4JBridge b2 = new Py4JBridge(bytesPerValue, penaltyNs);
        new PandasUdfProcessor(b2, batchSize).computeFees(engine.freshCopy());
        b2.report("PandasUDF");

        // 3) Built-in — no crossing.
        Py4JBridge b3 = new Py4JBridge(bytesPerValue, penaltyNs);
        List<Trade> builtInRows = engine.freshCopy();
        new BuiltInExpression().computeFees(builtInRows);
        b3.report("BuiltIn");

        log.info(() -> "Sample fee for TRD-1 = " + builtInRows.get(0).fee);
    }
}
